let viewedProfileId;const profileStyle=document.createElement('link');profileStyle.rel='stylesheet';profileStyle.href='profile.css?v=20260612-company-1';document.head.appendChild(profileStyle);const profileDialog=document.createElement('dialog');profileDialog.className='modal trust-modal';profileDialog.innerHTML='<button class="modal-close" type="button" id="closeTrustProfile">&times;</button><div id="trustProfileContent"></div>';document.body.appendChild(profileDialog);document.getElementById('closeTrustProfile').addEventListener('click',()=>profileDialog.close());
function companyImage(company,size='large'){return company.profileImage?`<img class="company-profile-image ${size}" src="${escapeHtml(company.profileImage)}" alt="${escapeHtml(company.name)} profile picture">`:`<span class="company-profile-placeholder ${size}">${initials(company.name)}</span>`}function companyFacts(company){return[company.yearFounded&&`Founded ${company.yearFounded}`,company.employeeCount&&`${company.employeeCount} employees`,[company.city,company.state].filter(Boolean).join(', ')].filter(Boolean).join(' · ')}
async function loadTrustProfile(companyId,open=true){try{const p=await api(`/api/profiles/${companyId}`);viewedProfileId=companyId;const credential=x=>`<article class="credential-profile-card"><span class="connection-status ${new Date(x.expiresAt)>=new Date()?'accepted':''}">${escapeHtml(x.verificationStatus)}</span><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.type)}${x.issuer?` · ${escapeHtml(x.issuer)}`:''}</p><small>${x.credentialNumber?`Number: ${escapeHtml(x.credentialNumber)} · `:''}${x.expiresAt?`Expires ${escapeHtml(x.expiresAt)}`:'No expiration provided'}</small>${x.coverage?`<strong>${escapeHtml(x.coverage)}</strong>`:''}</article>`;const project=x=>`<article class="portfolio-card"><img src="${escapeHtml(x.photoUrl)}" alt="${escapeHtml(x.title)}"><div><span class="trade-pill">${escapeHtml(x.trade||'Completed work')}</span><h3>${escapeHtml(x.title)}</h3><p>${escapeHtml(x.description||'')}</p><small>${escapeHtml([x.city,x.state].filter(Boolean).join(', '))}${x.completedAt?` · ${escapeHtml(x.completedAt)}`:''}</small></div></article>`;const contact=[p.company.phone,p.company.contactEmail,p.company.website].filter(Boolean).map(x=>`<span>${escapeHtml(x)}</span>`).join('');profileDialog.querySelector('#trustProfileContent').innerHTML=`<div class="trust-profile-heading company-public-heading">${companyImage(p.company)}<div><span class="kicker">Company profile</span><h2>${escapeHtml(p.company.name)}</h2><p>${escapeHtml(p.company.trades.join(' · ')||'Trades not listed')}</p><small>${escapeHtml(companyFacts(p.company))}</small></div></div>${p.company.about?`<section class="company-about"><h3>About the company</h3><p>${escapeHtml(p.company.about)}</p></section>`:''}${contact?`<div class="company-contact-strip">${contact}</div>`:''}<section><h3>Licenses, insurance, and credentials</h3><div class="credential-profile-grid">${p.credentials.length?p.credentials.map(credential).join(''):'<div class="list-empty">No credential information posted yet.</div>'}</div></section><section><h3>Recent completed work</h3><div class="portfolio-grid">${p.portfolio.length?p.portfolio.map(project).join(''):'<div class="list-empty">No completed-work photos posted yet.</div>'}</div></section><p class="due-diligence-note">Credential information is self-reported during the private alpha. Contractors should independently confirm licenses, insurance coverage, expiration dates, and applicability before hiring.</p>`;if(open)profileDialog.showModal();if(p.isOwner)renderProfileManager(p)}catch(error){showNotice(error.message,true)}}
function renderProfileManager(p){const root=document.getElementById('profileDetails'),isSub=dashboard.company.capabilities.includes('subcontractor'),company=p.company;root.innerHTML=`<div class="company-profile-editor"><div class="company-picture-panel">${companyImage(company)}<div><strong>Company profile picture</strong><p>Upload a logo or a clear photo that represents your company.</p><label class="button button-outline upload-button">Choose image<input id="companyImageInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button class="text-link" id="removeCompanyImage" type="button" ${company.profileImage?'':'hidden'}>Remove image</button></div></div><form class="workspace-card company-info-form" id="companyInfoForm"><span class="kicker">Company information</span><h3>Tell contractors and trade partners about your business</h3><label><span>About the company</span><textarea name="about" rows="5" maxlength="1800" placeholder="Describe your experience, specialties, team, and the kinds of projects you take on.">${escapeHtml(company.about||'')}</textarea></label><div class="form-row"><label><span>Phone</span><input name="phone" value="${escapeHtml(company.phone||'')}" placeholder="(214) 555-0123"></label><label><span>Public contact email</span><input name="contactEmail" type="email" value="${escapeHtml(company.contactEmail||'')}" placeholder="estimating@company.com"></label></div><label><span>Website</span><input name="website" value="${escapeHtml(company.website||'')}" placeholder="https://company.com"></label><div class="form-row"><label><span>Year founded</span><input name="yearFounded" inputmode="numeric" maxlength="4" value="${escapeHtml(company.yearFounded||'')}" placeholder="2012"></label><label><span>Company size</span><select name="employeeCount"><option value="">Select size</option>${['1-5','6-10','11-25','26-50','51-100','100+'].map(x=>`<option ${company.employeeCount===x?'selected':''}>${x}</option>`).join('')}</select></label></div><button class="button button-orange" type="submit">Save company profile</button></form></div>${isSub?`<div class="profile-manage-grid"><form class="workspace-card trust-form" id="portfolioForm"><span class="kicker">Completed work</span><h3>Add a recent project</h3><label><span>Project title</span><input name="title" required></label><div class="form-row"><label><span>Trade</span><input name="trade"></label><label><span>Completion date</span><input name="completedAt" type="date"></label></div><div class="form-row"><label><span>City</span><input name="city"></label><label><span>State</span><input name="state" maxlength="2"></label></div><label><span>Photo image URL</span><input name="photoUrl" type="url" required placeholder="https://..."></label><label><span>Description</span><textarea name="description" rows="3"></textarea></label><button class="button button-orange" type="submit">Add completed work</button></form><form class="workspace-card trust-form" id="credentialForm"><span class="kicker">Due diligence</span><h3>Add license or insurance</h3><label><span>Type</span><select name="type" required><option value="license">License</option><option value="insurance">Insurance</option><option value="certification">Certification</option><option value="bond">Bond</option></select></label><label><span>Name</span><input name="name" required placeholder="General liability insurance"></label><div class="form-row"><label><span>Issuer</span><input name="issuer"></label><label><span>Number</span><input name="credentialNumber"></label></div><div class="form-row"><label><span>Issuing state</span><input name="state" maxlength="2"></label><label><span>Expires</span><input name="expiresAt" type="date"></label></div><label><span>Coverage or classification</span><input name="coverage" placeholder="$2M aggregate or license class"></label><label><span>Notes</span><textarea name="notes" rows="2"></textarea></label><button class="button button-dark" type="submit">Add credential information</button></form></div>`:''}<button class="button button-outline" id="previewTrustProfile" type="button">Preview public profile</button>`;let profileImage=company.profileImage||'';document.getElementById('companyImageInput').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(file.size>1500000){showNotice('Choose an image under 1.5 MB.',true);event.target.value='';return}const reader=new FileReader();reader.onload=()=>{profileImage=reader.result;document.querySelector('.company-picture-panel').firstElementChild.outerHTML=companyImage({...company,profileImage})};reader.readAsDataURL(file)});document.getElementById('removeCompanyImage').addEventListener('click',()=>{profileImage='';document.querySelector('.company-picture-panel').firstElementChild.outerHTML=companyImage({...company,profileImage});document.getElementById('removeCompanyImage').hidden=true});document.getElementById('companyInfoForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;button.textContent='Saving...';try{await api('/api/profile/company',{method:'PUT',body:JSON.stringify({...Object.fromEntries(new FormData(event.currentTarget)),profileImage})});await refresh();await loadTrustProfile(dashboard.company.id,false);showNotice('Company profile saved.')}catch(error){showNotice(error.message,true)}finally{button.disabled=false;button.textContent='Save company profile'}});if(isSub){document.getElementById('portfolioForm').addEventListener('submit',e=>submitTrust(e,'/api/profile/portfolio'));document.getElementById('credentialForm').addEventListener('submit',e=>submitTrust(e,'/api/profile/credentials'))}document.getElementById('previewTrustProfile').addEventListener('click',()=>loadTrustProfile(dashboard.company.id))}
async function submitTrust(event,path){event.preventDefault();try{await api(path,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});event.currentTarget.reset();await loadTrustProfile(dashboard.company.id,false);showNotice('Trust profile updated.')}catch(error){showNotice(error.message,true)}}function addProfileButtons(){document.querySelectorAll('[data-message-bid],[data-connect],[data-request]').forEach(button=>{const id=button.dataset.messageBid||button.dataset.connect||button.dataset.request,container=button.closest('.directory-card,.bid-card');if(container&&!container.querySelector('[data-trust-profile]')){const x=document.createElement('button');x.type='button';x.className='text-link';x.dataset.trustProfile=id;x.textContent='View profile';container.querySelector('.connection-actions,.market-job-actions')?.appendChild(x)}});document.querySelectorAll('[data-trust-profile]').forEach(button=>button.onclick=()=>loadTrustProfile(button.dataset.trustProfile))}new MutationObserver(addProfileButtons).observe(document.body,{childList:true,subtree:true});document.querySelector('[data-view="profile"]').addEventListener('click',()=>loadTrustProfile(dashboard.company.id,false));const profileRefresh=refresh;refresh=async function(){await profileRefresh();await loadTrustProfile(dashboard.company.id,false);addProfileButtons()};
